assert len(TRIALS)==50 and len({x[1] for x in TRIALS})==50

def records():
    out=[]
    for i,(name,kind,players,w,d,h,silhouette,goal,death) in enumerate(TRIALS,1):
        out.append(dict(id=i,name=name,kind=kind,players=players,minPlayers=4 if kind in ('tetris','teamescape','oxygen','switches') else 2 if kind in ('duel','balance') else 1,
          width=w,depth=d,height=h,footprint=w*d,floors=3 if kind in ('snake','tower','wheel','risingwater') else 2,
          silhouette=silhouette,rules=goal,death=death,reward=60+i*2,duration=100 if kind in ('maze','teamescape','tetris') else 75,
          story=f'Sector {i:02}: an abandoned civic machine was converted into a regulated trial. The maintenance entrance records its last safe inspection.',
          material=['Concrete','Slate','Metal','Marble','Basalt','Ice','Brick','WoodPlanks'][((i-1)//6)%8]))
    return out
